namespace ghidra.app.plugin.core.debug.gui.breakpoint;



using db;
using ghidra.debug.api.breakpoint;
using ghidra.debug.api.breakpoint.LogicalBreakpoint;
using ghidra.pcode.exec;
using ghidra.program.model.address;
using ghidra.program.util;
using ghidra.trace.model.breakpoint;
using ghidra.trace.model.breakpoint;

public class BreakpointLocationRow {
	private DebuggerBreakpointsProvider provider;
	private TraceBreakpointLocation loc;

	public BreakpointLocationRow(DebuggerBreakpointsProvider provider,
			TraceBreakpointLocation loc) {
		this.provider = provider;
		this.loc = loc;
	}

	private long getSnap() {
		return provider.traceManager.getCurrentFor(loc.getTrace()).getSnap();
	}

	public string getName() {
		return loc.getName(getSnap());
	}

	public bool isEnabled() {
		return loc.isEnabled(getSnap());
	}

	public State getState() {
		LogicalBreakpoint lb = provider.breakpointService.getBreakpoint(loc);
		if (lb == null) {
			return State.NONE; // Should only happen in transition
		}
		return lb.computeStateForLocation(loc);
	}

	public void setEnabled(bool enabled) {
		if (enabled) {
			provider.breakpointService.enableLocs(Set.of(loc)).exceptionally(ex => {
				provider.breakpointError("Toggle breakpoint", "Could not enable breakpoint", ex);
				return null;
			});
		}
		else {
			provider.breakpointService.disableLocs(Set.of(loc)).exceptionally(ex => {
				provider.breakpointError("Toggle breakpoint", "Could not disable breakpoint", ex);
				return null;
			});
		}
	}

	public void setState(State state) {
		System.Diagnostics.Debug.Assert(state.isNormal());
		setEnabled(state.isEnabled());
	}

	public void setName(string name) {
		using (Transaction tid = loc.getTrace().openTransaction("Set breakpoint name"))
{
			loc.setName(getSnap(), name);
		}
	}

	public Address getAddress() {
		return loc.getMinAddress(getSnap());
	}

	public ProgramLocation getProgramLocation() {
		return new ProgramLocation(loc.getTrace().getProgramView(), getAddress());
	}

	public string getTraceName() {
		return loc.getTrace().getName();
	}

	public string getComment() {
		return loc.getComment(getSnap());
	}

	public void setComment(string comment) {
		using (Transaction tid = loc.getTrace().openTransaction("Set breakpoint comment"))
{
			loc.setComment(getSnap(), comment);
		}
	}

	public string getExpression() {
		TraceBreakpointSpec spec = loc.getSpecification();
		if (spec == null) {
			// Shouldn't happen, but may in the interim
			return "";
		}
		return spec.getExpression(getSnap());
	}

	public bool hasSleigh() {
		return !SleighUtils.UNCONDITIONAL_BREAK.equals(loc.getEmuSleigh(getSnap()));
	}

	public TraceBreakpointLocation getTraceBreakpoint() {
		return loc;
	}
}
